import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

/**
 * Where uploaded files live. Today: a folder on your Mac.
 * For SaaS: an S3 implementation of the same three methods.
 */
export interface FileStore {
  put(key: string, bytes: Uint8Array): Promise<void>;
  get(key: string): Promise<Uint8Array | null>;
  delete(key: string): Promise<void>;
}

const SAFE_KEY = /^[a-zA-Z0-9._-]+$/;

export class LocalFileStore implements FileStore {
  constructor(private readonly dir: string) {}

  private path(key: string) {
    // Keys are generated by us (uuid + extension), but never trust a path segment.
    if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error(`Invalid file key: ${key}`);
    return join(this.dir, key);
  }

  async put(key: string, bytes: Uint8Array) {
    await mkdir(this.dir, { recursive: true });
    await writeFile(this.path(key), bytes);
  }

  async get(key: string) {
    try {
      return new Uint8Array(await readFile(this.path(key)));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw err;
    }
  }

  async delete(key: string) {
    await rm(this.path(key), { force: true });
  }
}

/** In-memory version for tests. */
export class MemoryFileStore implements FileStore {
  readonly files = new Map<string, Uint8Array>();
  async put(key: string, bytes: Uint8Array) {
    this.files.set(key, bytes);
  }
  async get(key: string) {
    return this.files.get(key) ?? null;
  }
  async delete(key: string) {
    this.files.delete(key);
  }
}
